fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out = std::env::args().nth(1).ok_or("output directory missing")?;
    std::fs::create_dir_all(&out)?;
    let mut config = prost_build::Config::new();
    config.protoc_executable("protoc/bin/protoc");
    config.btree_map(["."]);
    tonic_prost_build::configure()
        .build_client(true)
        .build_server(false)
        .emit_rerun_if_changed(false)
        .out_dir(out)
        .compile_with_config(config, &["api.proto"], &["."])?;
    let _pod = k8s_openapi::api::core::v1::Pod::default();
    Ok(())
}
